Rules.InvariantScript:
With(
    {
        req: Coalesce(varCurrentAsset.CommissioningRequired.Value, "None"),
        done: Concat(varCurrentAsset.CommissioningDone, Value, " | ")
    },
    If(
        req = "None",                       "Not required",
        // Commissioned at this campus, among possibly several.
        !IsBlank(Find(req, done)),          "Commissioned",
        // An extended commissioning covers the administrative one.
        req = "administrative"
            && !IsBlank(Find("extended", done)),
                                            "Commissioned",
        IsBlank(done),                      "Not commissioned",
        // Something was done, but not what this asset needs.
        "Incomplete"
    )
)

With(
    {
        req: Coalesce(varCurrentAsset.CommissioningRequired.Value, "None"),
        done: Concat(varCurrentAsset.CommissioningDone, Value, " | ")
    },
    If(
        req = "None",                       RGBA(16, 124, 16, 1),
        // Commissioned at this campus, among possibly several.
        !IsBlank(Find(req, done)),          RGBA(16, 124, 16, 1),
        // An extended commissioning covers the administrative one.
        req = "administrative"
            && !IsBlank(Find("extended", done)),
                                            RGBA(16, 124, 16, 1),
        IsBlank(done),                      RGBA(168, 0, 0, 1),
        // Something was done, but not what this asset needs.
        RGBA(196, 116, 0, 1)
    )
)

If(
    varCurrentAsset.'Id (ID)' in colMoveBuffer.'Id (ID)',
    Notify("This asset is already in the move list.", NotificationType.Warning),
    Collect(colMoveBuffer, varCurrentAsset)
);
Navigate(scr_Move, ScreenTransition.Fade)

Set(varCurrentBooking, Blank());
// Also clear the setup, otherwise a setup opened earlier would
// still be pre-selected on the booking form.
Set(varCurrentSetup, Blank());
Navigate(scr_BookingDetail, ScreenTransition.Fade)

Set(varBookingDevice, varCurrentAsset.Titel);
Set(varBookingView, "calendar");
Set(varCalMonth, Date(Year(Today()), Month(Today()), 1));
Navigate(scr_Bookings, ScreenTransition.Fade)
